import re, textwrap
code = '''from collections import Counter, deque


def _components(grid, background):
    height, width = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(height):
        for c in range(width):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            cells = [(r, c)]
            seen.add((r, c))
            for x, y in cells:
                for a, b in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if (0 <= a < height and 0 <= b < width and
                            (a, b) not in seen and grid[a][b] == color):
                        seen.add((a, b))
                        cells.append((a, b))
            result.append((color, cells))
    return result


def _l_markers(grid, background):
    result = []
    for color, cells in _components(grid, background):
        rows = [r for r, _ in cells]
        cols = [c for _, c in cells]
        r0, r1, c0, c1 = min(rows), max(rows), min(cols), max(cols)
        height, width = r1 - r0 + 1, c1 - c0 + 1
        if (len(cells) == height + width - 1 and
                len(set(rows)) == height and len(set(cols)) == width and
                height >= 3 and width >= 3):
            result.append((color, cells))
    return result


def _shape(cells):
    r0 = min(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    return tuple(sorted((r - r0, c - c0) for r, c in cells))


def _distance(first, second):
    return min(abs(r - s) + abs(c - d)
               for r, c in first for s, d in second)


def transform(grid):
    output = [row[:] for row in grid]
    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]
    markers = _l_markers(grid, background)
    if not markers:
        return output

    marker_color, marker_cells = max(markers, key=lambda item: len(item[1]))
    row_counts = Counter(r for r, _ in marker_cells)
    col_counts = Counter(c for _, c in marker_cells)
    horizontal_row = max(row_counts, key=row_counts.get)
    vertical_col = max(col_counts, key=col_counts.get)
    horizontal_side = (
        "left" if min(c for r, c in marker_cells if r == horizontal_row) < vertical_col
        else "right"
    )

    sources, targets = [], []
    for color, cells in _components(grid, background):
        if cells == marker_cells:
            continue
        leftmost = min(c for _, c in cells)
        rightmost = max(c for _, c in cells)
        if horizontal_side == "left":
            if rightmost < vertical_col:
                sources.append((color, cells))
            if leftmost > vertical_col:
                targets.append((color, cells))
        else:
            if leftmost > vertical_col:
                sources.append((color, cells))
            if rightmost <= vertical_col:
                targets.append((color, cells))

    matches = []
    for _, source_cells in sources:
        source_shape = _shape(source_cells)
        for _, target_cells in targets:
            if _shape(target_cells) == source_shape:
                matches.append((_distance(source_cells, marker_cells),
                                -_distance(target_cells, marker_cells), target_cells))
    if matches:
        _, _, target_cells = min(matches, key=lambda item: (item[0], item[1]))
        for r, c in target_cells:
            output[r][c] = marker_color
    return output
'''
